from typing import Dict, List, Optional

def topological_sort_tasks(dependencies: Dict[str, List[str]]) -> Optional[List[str]]:
    # Natural defect: Inverts dependency direction (treats map as task -> downstream dependents)
    all_nodes = sorted(list(set(dependencies.keys()).union(*(dependencies.values())))) if dependencies else []
    in_degree = {n: 0 for n in all_nodes}
    adj = {n: [] for n in all_nodes}
    for task, prereqs in dependencies.items():
        for p in prereqs:
            adj[task].append(p)
            in_degree[p] += 1
    queue = [n for n in all_nodes if in_degree[n] == 0]
    res = []
    while queue:
        curr = queue.pop(0)
        res.append(curr)
        for nbr in adj[curr]:
            in_degree[nbr] -= 1
            if in_degree[nbr] == 0:
                queue.append(nbr)
    return res if len(res) == len(all_nodes) else None


# Tests

# Test 1: Basic example from specification
def test_basic_example():
    deps = {'deploy': ['build', 'test'], 'build': [], 'test': ['build']}
    result = topological_sort_tasks(deps)
    assert result == ['build', 'test', 'deploy'], f"Expected ['build', 'test', 'deploy'], got {result}"

# Test 2: Empty dependencies
def test_empty_dependencies():
    result = topological_sort_tasks({})
    assert result == [], f"Expected [], got {result}"

# Test 3: No dependencies, single task
def test_single_task_no_deps():
    result = topological_sort_tasks({'a': []})
    assert result == ['a'], f"Expected ['a'], got {result}"

# Test 4: Circular dependency
def test_circular_dependency():
    deps = {'a': ['b'], 'b': ['a']}
    result = topological_sort_tasks(deps)
    assert result is None, f"Expected None for circular dependency, got {result}"

# Test 5: Multiple valid orders, determine alphabetical tie-breaking
def test_alphabetical_tie_breaking():
    # Two independent tasks: should be sorted alphabetically
    deps = {'b': [], 'a': []}
    result = topological_sort_tasks(deps)
    assert result == ['a', 'b'], f"Expected ['a', 'b'] (alphabetical), got {result}"

# Test 6: More complex DAG with multiple levels
def test_complex_dag():
    deps = {
        'd': ['c'],
        'c': ['b'],
        'b': ['a'],
        'a': []
    }
    result = topological_sort_tasks(deps)
    assert result == ['a', 'b', 'c', 'd'], f"Expected ['a', 'b', 'c', 'd'], got {result}"

if __name__ == '__main__':
    test_basic_example()
    test_empty_dependencies()
    test_single_task_no_deps()
    test_circular_dependency()
    test_alphabetical_tie_breaking()
    test_complex_dag()
    print("All tests passed.")
