    # Extract query string
    if '?' in url_or_query:
        # Split at the first '?'
        parts = url_or_query.split('?', 1)
        query_string = parts[1] if len(parts) > 1 else ''
        # Handle fragment
        if '#' in query_string:
            query_string = query_string.split('#', 1)[0]
    else:
        query_string = url_or_query
        if '#' in query_string:
            query_string = query_string.split('#', 1)[0]

    if not query_string:
        return ''

    # Parse query string preserving order of values
    # parse_qs returns dict of lists, but we need to handle empty values and order
    pairs = []
    for param in query_string.split('&'):
        if not param:
            continue
        if '=' in param:
            key, value = param.split('=', 1)
            pairs.append((key, value))
        else:
            pairs.append((param, ''))

    # Drop keys
    if drop_keys:
        drop_set = set(k.lower() for k in drop_keys)
        pairs = [(k, v) for k, v in pairs if k.lower() not in drop_set]

    if not pairs:
        return ''

    # Sort by key, preserving order of values for same key
    from collections import OrderedDict
    ordered_dict = OrderedDict()
    for k, v in pairs:
        if k not in ordered_dict:
            ordered_dict[k] = []
        ordered_dict[k].append(v)

    # Sort keys alphabetically (case-sensitive sort is typical for canonicalization, 
    # but spec says "alphabetically" - usually means case-insensitive or standard string sort.
    # Let's assume standard string sort for keys, but the spec says "case-insensitive comparison" for dropping.
    # For sorting, "alphabetically" usually implies case-insensitive as well, or just sorted().
    # Let's use case-insensitive sort for keys to be consistent with typical canonicalization.
    sorted_keys = sorted(ordered_dict.keys(), key=lambda x: x.lower())

    # Reconstitute
    result_parts = []
    for k in sorted_keys:
        for v in ordered_dict[k]:
            result_parts.append(f"{k}={v}")

    return '&'.join(result_parts)

