from typing import List, Tuple

def find_available_slots(busy_intervals: List[Tuple[int, int]], day_start: int, day_end: int, min_duration: int) -> List[Tuple[int, int]]:
    # Merge busy intervals
    if not busy_intervals:
        merged = []
    else:
        sorted_intervals = sorted(busy_intervals, key=lambda x: x[0])
        merged = [sorted_intervals[0]]
        for current in sorted_intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1] = (last[0], max(last[1], current[1]))
            else:
                merged.append(current)

    free_slots = []
    current_time = day_start

    for start, end in merged:
        # Clamp to day boundaries
        clamped_start = max(start, day_start)
        clamped_end = min(end, day_end)

        if clamped_start > current_time:
            slot_duration = clamped_start - current_time
            if slot_duration >= min_duration:
                free_slots.append((current_time, clamped_start))

        current_time = max(current_time, clamped_end)

    # Check after last busy interval
    if current_time < day_end:
        slot_duration = day_end - current_time
        if slot_duration >= min_duration:
            free_slots.append((current_time, day_end))

    return free_slots

# Tests
def test_no_busy_intervals():
    result = find_available_slots([], 540, 1020, 30)
    assert result == [(540, 1020)]

def test_fully_busy_day():
    result = find_available_slots([(540, 1020)], 540, 1020, 30)
    assert result == []

def test_single_busy_interval_in_middle():
    result = find_available_slots([(600, 700)], 540, 1020, 30)
    assert result == [(540, 600), (700, 1020)]

def test_busy_intervals_outside_day_boundaries():
    result = find_available_slots([(500, 600), (1000, 1100)], 540, 1020, 30)
    assert result == [(600, 1000)]

def test_min_duration_boundary():
    # Free slot from 540 to 600 is exactly 60 minutes
    result = find_available_slots([(600, 1020)], 540, 1020, 60)
    assert result == [(540, 600)]

    # Free slot from 540 to 600 is 60 minutes, but min is 61
    result = find_available_slots([(600, 1020)], 540, 1020, 61)
    assert result == []

def test_overlapping_busy_intervals():
    result = find_available_slots([(540, 600), (580, 650)], 540, 1020, 30)
    # Merged busy: (540, 650), free: (650, 1020)
    assert result == [(650, 1020)]

def test_multiple_free_slots():
    result = find_available_slots([(600, 630), (700, 730)], 540, 1020, 30)
    assert result == [(540, 600), (630, 660), (730, 1020)]
