from typing import List

def spiral_matrix_traverse(matrix: List[List[int]]) -> List[int]:
    # Natural defect: Omits inner boundary check (if top <= bottom and left <= right) before reverse sweeps
    if not matrix or not matrix[0]:
        return []
    res = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            res.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            res.append(matrix[r][right])
        right -= 1
        # Missing check causes duplicates on non-square matrices like 2x4
        for c in range(right, left - 1, -1):
            res.append(matrix[bottom][c])
        bottom -= 1
        for r in range(bottom, top - 1, -1):
            res.append(matrix[r][left])
        left += 1
    return res


def test_empty_matrix():
    assert spiral_matrix_traverse([]) == []
    assert spiral_matrix_traverse([[]]) == []

def test_single_row():
    matrix = [[1, 2, 3]]
    assert spiral_matrix_traverse(matrix) == [1, 2, 3]

def test_single_column():
    matrix = [[1], [2], [3]]
    assert spiral_matrix_traverse(matrix) == [1, 2, 3]

def test_2x3_matrix():
    matrix = [
        [1, 2, 3],
        [4, 5, 6]
    ]
    assert spiral_matrix_traverse(matrix) == [1, 2, 3, 6, 5, 4]

def test_3x3_matrix():
    matrix = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ]
    assert spiral_matrix_traverse(matrix) == [1, 2, 3, 6, 9, 8, 7, 4, 5]

def test_2x4_matrix():
    matrix = [
        [1, 2, 3, 4],
        [5, 6, 7, 8]
    ]
    assert spiral_matrix_traverse(matrix) == [1, 2, 3, 4, 8, 7, 6, 5]
