from typing import Optional, Dict, Any

def parse_semver(version_str: str) -> Optional[Dict[str, Any]]:
    """
    Parse a Semantic Versioning 2.0.0 string into components.
    Returns a dict with keys: 'major' (int), 'minor' (int), 'patch' (int), 'prerelease' (Optional[str]), 'build' (Optional[str]).
    Returns None if the string is not a valid semver format (must have major.minor.patch as non-negative ints without leading zeroes).
    Example: '1.2.3-alpha.1+build.001' -> {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': 'alpha.1', 'build': 'build.001'}
    """
    import re

    if not isinstance(version_str, str):
        return None

    # Semver regex:
    # Major: 0 or [1-9]\d*
    # Minor: 0 or [1-9]\d*
    # Patch: 0 or [1-9]\d*
    # Prerelease: optional, starts with '-', followed by dot-separated identifiers (alphanumeric and hyphens, no leading zeros for numeric)
    # Build: optional, starts with '+', followed by dot-separated identifiers (alphanumeric and hyphens)

    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, version_str)
    if not match:
        return None

    major, minor, patch, prerelease, build = match.groups()

    return {
        'major': int(major),
        'minor': int(minor),
        'patch': int(patch),
