from typing import List, Tuple

def merge_overlapping_intervals(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    # Natural defect: Strict inequality (< instead of <=) fails on contiguous intervals like (1, 4) and (4, 5)
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]
    for current in sorted_intervals[1:]:
        prev_start, prev_end = merged[-1]
        curr_start, curr_end = current
        if curr_start < prev_end:
            merged[-1] = (prev_start, max(prev_end, curr_end))
        else:
            merged.append(current)
    return merged

# Tests
def test_empty_list():
    assert merge_overlapping_intervals([]) == []

def test_single_interval():
    assert merge_overlapping_intervals([(1, 5)]) == [(1, 5)]

def test_overlapping_intervals():
    assert merge_overlapping_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]

def test_contiguous_intervals_should_merge():
    # Per spec, contiguous intervals like (1, 4) and (4, 7) should be merged into (1, 7)
    assert merge_overlapping_intervals([(1, 4), (4, 7)]) == [(1, 7)]

def test_multiple_overlaps_and_contiguous():
    assert merge_overlapping_intervals([(1, 3), (2, 6), (6, 9), (7, 10)]) == [(1, 10)]

def test_unsorted_input():
