def find_available_slots(busy_intervals: List[Tuple[int, int]], day_start: int, day_end: int, min_duration: int) -> List[Tuple[int, int]]:
    # Merge overlapping busy intervals
    if not busy_intervals:
        busy = []
    else:
        busy = sorted(busy_intervals)
        merged = [busy[0]]
        for start, end in busy[1:]:
            if start <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        busy = merged

    # Find free slots between day_start and day_end
    free_slots = []
    current = day_start
    for start, end in busy:
        if start > current:
            free_slots.append((current, min(start, day_end)))
        current = max(current, end)
        if current >= day_end:
            break
    if current < day_end:
        free_slots.append((current, day_end))

    # Filter by min_duration
    result = [(s, e) for s, e in free_slots if (e - s) >= min_duration]
    return result

# Unit tests
def test_no_busy_intervals():
    assert find_available_slots([], 540, 1020, 60) == [(540, 1020)]

def test_all_day_busy():
    assert find_available_slots([(540, 1020)], 540, 1020, 60) == []

def test_single_busy_interval_middle():
