def topological_sort_tasks(dependencies: Dict[str, List[str]]) -> Optional[List[str]]:
    """
    Compute a valid execution order for tasks given their prerequisite dependencies.
    Args:
        dependencies: Dict mapping task_name -> list of prerequisite task_names that must run before it.
    Returns:
        A list of all task names in valid execution order.
        If multiple valid orders exist, ties should be broken deterministically by alphabetical order.
        If a circular dependency cycle exists, returns None.
    Example: {'deploy': ['build', 'test'], 'build': [], 'test': ['build']} -> ['build', 'test', 'deploy']
    """
    # Build graph and in-degree count
    in_degree = {}
    graph = {}

    # Initialize all tasks
    for task in dependencies:
        if task not in in_degree:
            in_degree[task] = 0
        if task not in graph:
            graph[task] = []

    # Add edges from prerequisites to tasks
    for task, prereqs in dependencies.items():
        for prereq in prereqs:
            if prereq not in in_degree:
                in_degree[prereq] = 0
            if prereq not in graph:
                graph[prereq] = []
            graph[prereq].append(task)
            in_degree[task] += 1

    # Use a min-heap (priority queue) for alphabetical tie-breaking
    import heapq
    heap = []
    for task, degree in in_degree.items():
        if degree == 0:
            heapq.heappush(heap, task)

    result = []
    while heap:
        task = heapq.heappop(heap)
        result.append(task)
        for neighbor in graph[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(in_degree):
        return None

    return result


