from typing import List, Tuple

def find_available_slots(busy_intervals: List[Tuple[int, int]], day_start: int, day_end: int, min_duration: int) -> List[Tuple[int, int]]:
    # Merge busy intervals
    if not busy_intervals:
        return [(day_start, day_end)] if (day_end - day_start) >= min_duration else []

    # Sort by start time
    busy_intervals = sorted(busy_intervals, key=lambda x: x[0])

    # Merge overlapping or adjacent intervals
    merged = []
    for start, end in busy_intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    # Find free slots
    free_slots = []
    current = day_start
    for start, end in merged:
        if start > current:
            free_slots.append((current, start))
        current = max(current, end)
    if current < day_end:
        free_slots.append((current, day_end))

    # Filter by min_duration
    return [(s, e) for s, e in free_slots if (e - s) >= min_duration]

# Tests
def test_no_busy_intervals():
    assert find_available_slots([], 540, 1020, 60) == [(540, 1020)]

def test_all_day_busy():
    assert find_available_slots([(540, 1020)], 540, 1020, 60) == []

def test_single_busy_interval_in_middle():
    assert find_available_slots([(600, 700)], 540, 1020, 60) == [(540, 600), (700, 1020)]

def test_busy_interval_at_start():
    assert find_available_slots([(540, 600)], 540, 1020, 60) == [(600, 1020)]

def test_busy_interval_at_end():
    assert find_available_slots([(960, 1020)], 540, 1020, 60) == [(540, 960)]

def test_min_duration_filter():
    # Free slots: (540, 570) duration 30, (600, 1020) duration 420
    # With min_duration=60, only (600, 1020) should be returned
    assert find_available_slots([(570, 600)], 540, 1020, 60) == [(600, 1020)]

def test_overlapping_busy_intervals():
    # Merged busy: (540, 700)
    # Free: (700, 1020)
    assert find_available_slots([(540, 600), (580, 700)], 540, 1020, 60) == [(700, 1020)]

def test_multiple_free_slots():
