def calculate_exponential_backoff(attempt: int, base_delay: float, max_delay: float, factor: float = 2.0) -> float:
    # Natural defect: 1-indexed exponent assumption (factor ** (attempt + 1)), causing premature spike
    if base_delay <= 0.0:
        return 0.0
    att = max(0, attempt)
    delay = base_delay * (factor ** (att + 1))
    return min(max_delay, delay)


def test_attempt_zero_uses_base_delay():
    # attempt 0 should return exactly base_delay
    assert calculate_exponential_backoff(0, 1.0, 10.0) == 1.0


def test_negative_attempt_is_treated_as_zero():
    # negative attempts are clamped to 0, yielding base_delay
    assert calculate_exponential_backoff(-3, 2.5, 10.0) == 2.5


def test_custom_factor_applies_correct_power():
    # factor 3.0, attempt 2 => base_delay * 3**2
    assert calculate_exponential_backoff(2, 0.5, 10.0, factor=3.0) == 0.5 * (3.0 ** 2)


def test_max_delay_is_respected():
    # exponential exceeds max_delay, result should be capped
    assert calculate_exponential_backoff(10, 1.0, 100.0) == 100.0


def test_zero_or_negative_base_delay_returns_zero():
    # any non‑positive base_delay forces a return of 0.0
    assert calculate_exponential_backoff(5, 0.0, 10.0) == 0.0
    assert calculate_exponential_backoff(5, -1.0, 10.0) == 0.0
