from typing import List, Tuple

def find_available_slots(busy_intervals: List[Tuple[int, int]], day_start: int, day_end: int, min_duration: int) -> List[Tuple[int, int]]:
    # Merge busy intervals
    if not busy_intervals:
        busy = []
    else:
        # Clamp busy intervals to day bounds
        clamped = [(max(s, day_start), min(e, day_end)) for s, e in busy_intervals if max(s, day_start) < min(e, day_end)]
        clamped.sort()
        merged = []
        for start, end in clamped:
            if merged and start <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], end))
            else:
                merged.append((start, end))
        busy = merged

    # Find free slots
    free_slots = []
    current = day_start
    for start, end in busy:
        if current < start:
            free_slots.append((current, start))
        current = max(current, end)
    if current < day_end:
        free_slots.append((current, day_end))

    # Filter by min_duration
    result = [(s, e) for s, e in free_slots if e - s >= min_duration]
    return result

# Tests

def test_no_busy_intervals():
    assert find_available_slots([], 540, 1020, 60) == [(540, 1020)]

def test_all_busy():
    assert find_available_slots([(540, 1020)], 540, 1020, 60) == []

def test_single_busy_in_middle():
    # Busy from 600 to 720, free before and after
    assert find_available_slots([(600, 720)], 540, 1020, 30) == [(540, 600), (720, 1020)]

def test_min_duration_filtering():
    # Free slots: (540, 550) duration 10, (600, 720) duration 120, (730, 1020) duration 290
    assert find_available_slots([(550, 600), (720, 730)], 540, 1020, 60) == [(600, 720), (730, 1020)]

def test_overlapping_busy_intervals():
    # Overlapping busy intervals merge into one
    assert find_available_slots([(540, 600), (580, 650)], 540, 1020, 30) == [(650, 1020)]

def test_busy_outside_day_bounds():
    # Busy interval extends beyond day bounds, should be clamped
    assert find_available_slots([(500, 580)], 540, 1020, 30) == [(580, 1020)]
